<section class="section"><div class="eyebrow">NOTIFICATIONS</div><h1>Notifikasi</h1><div class="stack"><?php foreach($notifications as $n):?><div class="card notification"><div><span class="badge"><?=h($n['type'])?></span><b><?=h($n['title'])?></b></div><p><?=h($n['message'])?></p><small class="muted"><?=h($n['created_at'])?></small></div><?php endforeach;?><?php if(!$notifications):?><div class="empty card">Belum ada notifikasi.</div><?php endif;?></div></section>